            { id: "density", label: "Density" },
            { id: "mismatch", label: "Mismatch" },
            { id: "scatter", label: "Scatter" },
            { id: "pipeline", label: "Pipeline" },
          ]}
        />
        <ToggleGroup
          label="Metric"
          value={metric}
          onChange={setMetric}
          options={METRIC_OPTIONS.map((m) => ({ id: m.id, label: m.label }))}
        />
        <ToggleGroup
          label="Filter"
          value={desertFilter}
          onChange={setDesertFilter}
          options={[
