                          ?.payload?.full ?? "",
                      )
                    }
                  />
                  <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                    {densityBars.map((d) => (
                      <Cell
                        key={d.id}
                        fill={TIER_COLOR[d.tier] ?? "#64748b"}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Therapy-area tilt"
            subtitle="Share of rare-disease interventional country-uses"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={THERAPY_AREA_SHARE}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" unit="%" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="area"
                    width={128}
                    tick={{ fontSize: 10 }}
                  />
                  <Tooltip />
                  <Bar dataKey="sharePct" fill="#6366f1" radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "mismatch" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Patient share minus trial share"
            subtitle="Positive bars = under-represented in trial geography"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={mismatchBars}
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                  <YAxis
                    unit=" pp"
                    tick={{ fontSize: 11 }}
                    domain={[-30, 25]}
                  />
                  <Tooltip
                    formatter={(v: number) => [`${fmtNum(v, 1)} pp`, "Mismatch"]}
                    labelFormatter={(_, payload) =>
                      String(payload?.[0]?.payload?.full ?? "")
                    }
                  />
                  <Bar dataKey="mismatch" radius={[4, 4, 0, 0]}>
                    {mismatchBars.map((d) => (
                      <Cell
                        key={d.id}
                        fill={d.mismatch >= 0 ? "#e11d48" : "#0ea5e9"}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Normalized regional radar"
            subtitle="Each spoke scaled 0???100 within metric (shape, not absolute)"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <RadarChart data={radarRows}>
                  <PolarGrid stroke="#cbd5e1" />
                  <PolarAngleAxis
                    dataKey="metric"
                    tick={{ fontSize: 9, fill: "#475569" }}
                  />
                  {(
                    ["EUR", "AMR", "AFR", "SEAR"] as WhoRegionId[]
                  ).map((id) => (
                    <Radar
                      key={id}
                      name={id}
                      dataKey={id}
                      stroke={REGION_COLORS[id]}
                      fill={REGION_COLORS[id]}
                      fillOpacity={0.12}
                      strokeWidth={2}
                    />
                  ))}
                  <Tooltip />
                </RadarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "scatter" && (
