                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={44}
                    tick={{ fontSize: 12, fontWeight: 600 }}
                  />
                  <Tooltip
                    formatter={(v) => [
                      fmtNum(Number(v ?? 0), 2),
                      metricLabel,
                    ]}
                    labelFormatter={(_, payload) =>
