              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Therapy-area tilt"
            subtitle="Share of rare-disease interventional country-uses"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
